def make_question(index, row):
    tag, prompt, options, answer, reason = row
    opts = [{"id": chr(65+i), "text": text} for i, text in enumerate(options)]
    aid = next(o["id"] for o in opts if o["text"] == answer)
    refs = [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": l, "observedPattern": "公立學校社會科公開試題常見的都市化、土地利用與城鄉互動資料推理能力，經本題重新設計。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u,t,l in SOURCES]
    steps = [f"讀題定位：圈出「{tag}」的人口、土地利用、交通、功能、服務、時間與群體。", f"整理證據：分開都市成長現象、機會、成本與分配結果；核心理由是「{reason}」。", f"核對正解：選項 {aid}「{answer}」符合都市化與城鄉互動資料的判讀。", "排除誘答：檢查是否只看高樓、房價、道路長度或全市平均，並找出被忽略的空間與公平。", "結論回查：確認分區、時間序列、流量與受影響群體一致；地方條件改變時重新判斷。"]
    return {"id": f"question-social-content-geo-af-iv-2-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-geo-af-iv-2"], "difficulty": "medium", "answer": {"value": aid, "explanation": reason}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。", "authoringNote": "依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫都市發展與都市化情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-geo-af-iv-2", "examPatternRefs": refs, "solutionStrategy": "先讀人口、土地利用與交通變化，再辨識都市功能與城鄉互動，最後比較便利、成本、環境與公平。", "solutionSteps": steps}

for index, row in enumerate(DATA, 1):
    (OUT / f"question-social-content-geo-af-iv-2-{index}.json").write_text(json.dumps(make_question(index, row), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
